import {vendorConfig} from './vendor-config.js';

const e=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const stages=[
  ['Arrive','Recognize the Harborline brand','Maya enters a franchise portal with the right brand, terms, language and support path.'],
  ['Register','Create an External ID identity','The sign-up flow collects the minimum identity attributes and supports the configured authentication methods.'],
  ['Verify','Connect the person to a franchise','A trusted franchise registry or approval process confirms company, agreement and location context.'],
  ['Authorize','Issue intentional application context','The application maps Maya to an owner role and the locations she may manage.'],
  ['Operate','Work inside the approved boundary','Server-side checks allow Downtown and Airport while denying Riverside, regardless of the interface.'],
  ['Step up','Protect a sensitive change','A financial or ownership change can require stronger assurance and a fresh authorization check.'],
  ['Delegate','Add a store manager safely','Maya can request delegation, while the application limits role, location and duration.'],
  ['Transfer','Change or end the relationship','A sale, closure or expired agreement removes location access and leaves evidence.'],
  ['Prove','Correlate identity and business events','Sign-in, token, approval and application audit records explain the final outcome.']
];
const locations=[
  {id:'DT-014',name:'Downtown',city:'Seattle, WA',state:'Active',access:'Owner',tone:'green'},
  {id:'AP-022',name:'Airport',city:'SeaTac, WA',state:'Opening soon',access:'Owner',tone:'violet'},
  {id:'RV-031',name:'Riverside',city:'Renton, WA',state:'Outside your franchise',access:'Blocked',tone:'locked'}
];
const proof=[
  ['User-flow association','Show the application is associated with the intended External ID user flow.'],
  ['Identity event','Match Maya, the application, timestamp, authentication method and result.'],
  ['Business verification','Show the trusted approval or franchise-registry decision that linked Maya to Northstar Foods.'],
  ['Allowed location','Demonstrate a server-authorized request for Downtown or Airport.'],
  ['Denied location','Demonstrate Riverside is denied by the API, not merely hidden in the interface.'],
  ['Lifecycle evidence','Show delegation, agreement change or removal in application audit records.']
];
let view='experience',scene='welcome',stageIndex=0,selectedLocation=null;
const checked=new Set();

function liveLink(){return vendorConfig.franchisePortalUrl?`<a class="primary" href="${e(vendorConfig.franchisePortalUrl)}" target="_blank" rel="noopener noreferrer">Open live franchise portal ↗</a>`:`<button class="outline" disabled title="The live franchise application URL has not been verified">Live portal · connection pending</button>`;}
function constellation(){return `<div class="franchise-map" aria-label="Franchise identity and location scope"><svg viewBox="0 0 540 310" aria-hidden="true"><defs><linearGradient id="franchise-line" x1="0" x2="1"><stop stop-color="#ffbf66"/><stop offset="1" stop-color="#bf8cff"/></linearGradient></defs><path d="M270 154 90 74M270 154 450 74M270 154 90 242M270 154 450 242"/><circle cx="270" cy="154" r="75"/><circle cx="270" cy="154" r="112"/></svg><div class="franchise-core"><small>EXTERNAL ID</small><strong>MC</strong><span>Maya Chen</span></div><div class="franchise-node n1"><b>01</b><span>Franchise<br>identity</span></div><div class="franchise-node n2"><b>02</b><span>Business<br>verified</span></div><div class="franchise-node n3"><b>03</b><span>Owner +<br>locations</span></div><div class="franchise-node n4"><b>04</b><span>Scoped<br>operations</span></div><div class="franchise-orbit-label">PERSON → FRANCHISE → LOCATION → ACTION</div></div>`;}
function journey(){const active=view==='experience'?(scene==='welcome'?0:4):view==='architecture'?stageIndex:8;return `<div class="vendor-journey franchise-journey" aria-label="Maya’s franchise identity lifecycle"><span>FRANCHISE JOURNEY</span>${stages.map((s,i)=>`<button data-franchise="journey" data-index="${i}" class="${i===active?'active':''}" ${i===active?'aria-current="step"':''}><b>${String(i+1).padStart(2,'0')}</b><small>${e(s[0])}</small></button>`).join('')}</div>`;}
function welcome(){return `<div class="franchise-preview-note"><span>GUIDED PREVIEW</span> Sample franchise data · real sign-in and authorization require a connected application</div><div class="vendor-experience-path franchise-path"><span><b>01</b> Join the brand</span><span><b>02</b> Verify the business</span><span><b>03</b> Receive store scope</span><span><b>04</b> Operate safely</span></div><section class="franchise-portal"><header class="franchise-brand"><a href="#maya/experience"><span>H</span> HARBORLINE</a><div>FRANCHISE OPERATIONS</div><small>${scene==='dashboard'?'Maya Chen · sample view':'Owner access'}</small></header>${scene==='welcome'?`<div class="franchise-welcome"><div class="franchise-welcome-copy"><span class="franchise-kicker">MEET MAYA CHEN · FRANCHISE OWNER</span><h2>One identity.<br>Three locations.<br><em>Only the right access.</em></h2><p>Maya is opening a second Harborline location. She needs one recognizable account, a verified relationship to Northstar Foods and precise authority for each store.</p><div class="franchise-benefits"><span>Branded onboarding</span><span>Location-scoped access</span><span>Delegated operations</span></div></div><div class="franchise-entry"><div class="franchise-seal">HC</div><span class="franchise-kicker">HARBORLINE FRANCHISE NETWORK</span><h3>Welcome, franchise partners</h3><p>Register or return through Microsoft Entra External ID. Your verified franchise relationship determines which locations and actions the application allows.</p>${liveLink()}<button class="franchise-preview-button" data-franchise="preview">Explore Maya’s command center →</button><small>New owner? Business verification follows identity registration.</small></div></div>`:dashboard()}</section>${selectedLocation?locationDialog():''}`;}
function dashboard(){return `<div class="franchise-dashboard"><div class="franchise-dashboard-head"><div><span class="franchise-kicker">ILLUSTRATIVE FRANCHISE EXPERIENCE</span><h2>Good morning, Maya.</h2><p>Northstar Foods LLC · franchise owner</p></div><button class="vendor-text-button" data-franchise="welcome">Back to welcome</button></div><div class="franchise-status"><div><small>IDENTITY</small><strong>External ID account</strong><span>Signed in</span></div><div><small>BUSINESS</small><strong>Northstar Foods LLC</strong><span>Verified relationship</span></div><div><small>AUTHORITY</small><strong>Owner</strong><span>2 approved locations</span></div><div><small>ASSURANCE</small><strong>Standard session</strong><span>Step-up for sensitive changes</span></div></div><div class="franchise-section-head"><div><span class="franchise-kicker">YOUR LOCATION BOUNDARY</span><h3>Operate the stores assigned to your franchise.</h3></div><span>2 allowed · 1 denied</span></div><div class="franchise-locations">${locations.map(l=>`<button class="franchise-location ${l.tone}" data-franchise="location" data-id="${l.id}"><span class="location-number">${e(l.id)}</span><span class="location-icon">${l.access==='Blocked'?'×':'H'}</span><strong>${e(l.name)}</strong><small>${e(l.city)}</small><em>${e(l.state)}</em><span class="location-access">${e(l.access)}</span></button>`).join('')}</div><div class="franchise-boundary"><div><span>WHY THIS MATTERS</span><strong>A valid identity does not grant every franchise location.</strong></div><p>The API must combine Maya’s verified franchise relationship, role, location assignments and requested action. The preview makes that boundary visible; a real demonstration must prove both an allowed and denied request.</p><a href="#maya/architecture">Reveal the control path →</a></div></div>`;}
function locationDialog(){const l=locations.find(x=>x.id===selectedLocation);if(!l)return '';const denied=l.access==='Blocked';return `<dialog id="franchise-location-dialog" aria-labelledby="franchise-dialog-title"><div class="modal-header"><h2 id="franchise-dialog-title">${e(l.name)} · ${e(l.id)}</h2><button class="quiet" data-franchise="close" aria-label="Close">✕</button></div><div class="modal-body"><span class="pill ${denied?'amber':'green'}">${denied?'Access denied':'Authorized location'}</span><h3>${denied?'The identity is valid. The location is not assigned.':'Maya can operate this location.'}</h3><p>${denied?'Riverside belongs to another franchise organization. A production API should return a denial even if someone constructs the request manually.':'The application matched Maya’s subject to Northstar Foods, her owner role and this approved location.'}</p><div class="franchise-decision"><span>SUBJECT</span><b>Maya Chen</b><span>FRANCHISE</span><b>${denied?'Northstar ≠ Riverside':'Northstar Foods LLC'}</b><span>DECISION</span><b>${denied?'DENY':'ALLOW'}</b></div><button class="primary" data-franchise="close">Return to locations</button></div></dialog>`;}
function architectureDiagram(){return `<section class="franchise-architecture"><div class="franchise-architecture-head"><div><span class="franchise-kicker">MAJORKEY / ARCHITECTURE STUDIO</span><h2>Turn a verified owner into location-scoped access.</h2><p>External ID authenticates Maya. Trusted business context and the application decide what she can do.</p></div><span>REFERENCE DESIGN · VERIFY IN TENANT</span></div><div class="franchise-lanes"><div>OWNER EXPERIENCE</div><div>EXTERNAL TENANT + TRUST</div><div>FRANCHISE APPLICATION</div></div><div class="franchise-diagram"><svg viewBox="0 0 1120 390" aria-label="Franchise External ID architecture"><defs><linearGradient id="flowline" x1="0" x2="1"><stop stop-color="#ffbf66"/><stop offset=".55" stop-color="#c58bff"/><stop offset="1" stop-color="#49e5c1"/></linearGradient><marker id="arrowhead" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0 8 4 0 8z" fill="#caa2ff"/></marker></defs><path class="flow" marker-end="url(#arrowhead)" d="M160 195 C230 195 245 105 335 105 S445 195 515 195 S630 285 710 285 S825 195 915 195"/><g transform="translate(70 135)"><circle cx="80" cy="60" r="58"/><text x="80" y="52">01</text><text class="big" x="80" y="77">Portal</text><text class="sub" x="80" y="100">Branded entry</text></g><g transform="translate(260 45)"><circle cx="80" cy="60" r="58"/><text x="80" y="52">02</text><text class="big" x="80" y="77">User flow</text><text class="sub" x="80" y="100">Authenticate</text></g><g transform="translate(450 135)"><circle cx="80" cy="60" r="58"/><text x="80" y="52">03</text><text class="big" x="80" y="77">Verify</text><text class="sub" x="80" y="100">Business context</text></g><g transform="translate(640 225)"><circle cx="80" cy="60" r="58"/><text x="80" y="52">04</text><text class="big" x="80" y="77">Claims</text><text class="sub" x="80" y="100">Stable contract</text></g><g transform="translate(850 135)"><circle cx="80" cy="60" r="58"/><text x="80" y="52">05</text><text class="big" x="80" y="77">API</text><text class="sub" x="80" y="100">Enforce scope</text></g><text class="edge" x="218" y="145">OIDC</text><text class="edge" x="405" y="145">identity</text><text class="edge" x="590" y="250">approved context</text><text class="edge" x="795" y="250">token + lookup</text></svg></div><div class="franchise-guardrails"><article><span>IDENTITY</span><strong>External ID subject</strong><p>Use a stable user identifier. Email alone is not the franchise authorization key.</p></article><article><span>BUSINESS CONTEXT</span><strong>Franchise registry</strong><p>Company, agreement, role and location assignments come from an authoritative business source.</p></article><article><span>ENFORCEMENT</span><strong>Application + API</strong><p>Every sensitive request is checked against current assignments and action-level policy.</p></article><article><span>EVIDENCE</span><strong>Correlated records</strong><p>Join identity, approval, token and application events with stable identifiers and time.</p></article></div></section>`;}
function architecture(){const s=stages[stageIndex];return `${architectureDiagram()}<section class="franchise-stage"><div><span class="franchise-kicker">STAGE ${String(stageIndex+1).padStart(2,'0')}</span><h3>${e(s[1])}</h3><p>${e(s[2])}</p></div><nav aria-label="Explore the control path">${stages.map((x,i)=>`<button data-franchise="stage" data-index="${i}" aria-pressed="${i===stageIndex}"><b>${String(i+1).padStart(2,'0')}</b>${e(x[0])}</button>`).join('')}</nav></section><div class="vendor-explain-grid"><section><span class="franchise-kicker">CUSTOMIZE FOR THE FRANCHISE MODEL</span><h3>Adapt the relationship, not just the page.</h3><p>Model owner, operator and store-manager roles; regional and location scope; agreement dates; brands; languages; sensitive actions; and delegation limits. Keep mutable assignments in a trusted system rather than treating self-asserted sign-up data as authorization.</p></section><section><span class="franchise-kicker">HOW AI HELPS</span><h3>Explain the access decision.</h3><p>An assistant can correlate supplied sign-in, approval and API records, identify missing evidence and draft a reversible recommendation. A human approves changes and the application remains the enforcement point.</p></section></div>`;}
function evidence(){return `<div class="vendor-proof-head"><div><span class="franchise-kicker">PROVE THE FRANCHISE BOUNDARY</span><h2>Show why Maya was allowed—or denied.</h2><p>Record each presenter check after showing the corresponding tenant or application evidence.</p></div><a class="outline" href="https://entra.microsoft.com/?tid=${vendorConfig.externalTenantId}" target="_blank" rel="noopener noreferrer">Open external tenant ↗</a></div><div class="vendor-evidence-list">${proof.map(([title,desc],i)=>`<label class="vendor-evidence"><input type="checkbox" data-franchise-proof="${i}" ${checked.has(i)?'checked':''}><span><strong>${e(title)}</strong><small>${e(desc)}</small></span><em>${checked.has(i)?'Presenter checked':'Not verified here'}</em></label>`).join('')}</div><div class="vendor-proof-summary" role="status">${checked.size} of ${proof.length} checks marked by presenter</div><section class="franchise-replay"><div><span class="franchise-kicker">RESET &amp; REPLAY</span><h3>Return to a known franchise state.</h3><p>Remove only prepared test delegation, restore the synthetic location assignments, clear the sample session and verify the starting state before repeating the story.</p></div><div><span class="franchise-kicker">CLIENT QUESTION</span><blockquote>Where does your application learn that this person represents this franchise, for these locations, right now?</blockquote></div></section>`;}
function narrative(){return `<section class="franchise-narrative"><div><span class="franchise-kicker">THE COMPLETE JOURNEY</span><h3>Maya grows the business without gaining access to the whole brand.</h3></div><p>Maya registers through a branded External ID flow, but registration proves only that she controls an identity. Harborline verifies Northstar Foods and its franchise agreement before assigning Downtown and Airport. The application uses that trusted relationship to authorize everyday work, requires stronger assurance for sensitive changes, and lets Maya delegate a narrowly scoped manager role. When a store transfers or the agreement ends, the application removes the relationship and preserves evidence. The audience sees one coherent lifecycle: identity, business trust, authorization, change and proof.</p></section>`;}

export function franchisePage(mode='experience'){view=['experience','architecture','evidence'].includes(mode)?mode:'experience';return `<div class="vendor-shell franchise-shell"><header class="vendor-topbar"><a href="#home"><img src="./assets/majorkey-logo.svg" alt="MajorKey" width="145" height="26"></a><span>MICROSOFT ENTRA EXTERNAL ID · FRANCHISE JOURNEY</span><a href="#home">← Choose a journey</a></header><main class="vendor-main"><section class="franchise-hero"><div class="franchise-hero-copy"><span class="franchise-kicker">MAYA CHEN · FRANCHISE OWNER</span><h1>Grow the network.<br><em>Keep every boundary.</em></h1><p>Follow one owner from branded registration through business verification, location-scoped operations, delegation and transfer.</p><div class="external-capabilities"><span>External tenant</span><span>Business verification</span><span>Location scope</span><span>Step-up + delegation</span></div><div class="external-hero-actions"><a class="primary" href="#maya/experience">Begin the journey →</a><button class="outline" data-franchise="desktop">Open protected desktop</button></div></div>${constellation()}</section><nav class="vendor-modes" aria-label="Maya’s journey">${[['experience','01','Experience'],['architecture','02','Architecture'],['evidence','03','Evidence']].map(([id,num,label])=>`<a href="#maya/${id}" ${view===id?'aria-current="page"':''}><span>${num}</span>${label}</a>`).join('')}</nav>${journey()}${view==='experience'?welcome():view==='architecture'?architecture():evidence()}${narrative()}<footer class="vendor-footer"><span>Harborline · MajorKey identity workshop</span><span>Live connection: ${vendorConfig.franchisePortalUrl?'franchise portal configured':'awaiting verified franchise application'}</span></footer></main></div>`;}

export function installFranchiseEvents(render,onDesktop){document.addEventListener('click',event=>{const button=event.target.closest('[data-franchise]');if(!button)return;const action=button.dataset.franchise;if(action==='desktop'){onDesktop();return;}if(action==='journey'){const i=Number(button.dataset.index);if(i===0){scene='welcome';location.hash='#maya/experience';}else if(i===4){scene='dashboard';location.hash='#maya/experience';}else if(i<8){stageIndex=i;location.hash='#maya/architecture';}else location.hash='#maya/evidence';render();return;}if(action==='preview')scene='dashboard';if(action==='welcome')scene='welcome';if(action==='stage')stageIndex=Number(button.dataset.index);if(action==='location')selectedLocation=button.dataset.id;if(action==='close')selectedLocation=null;render();const dialog=document.querySelector('#franchise-location-dialog');if(dialog){dialog.addEventListener('cancel',()=>{selectedLocation=null;},{once:true});dialog.showModal();}});document.addEventListener('change',event=>{if(!event.target.matches('[data-franchise-proof]'))return;const i=Number(event.target.dataset.franchiseProof);event.target.checked?checked.add(i):checked.delete(i);render();document.querySelector(`[data-franchise-proof="${i}"]`)?.focus();});}

export function mayaGuide(){const step=(action,why,look)=>({action,why,look});return {name:'Maya Chen',time:'Franchise journey',title:'Grow the network. Keep every boundary.',job:'Franchise owner',perspective:'Owner experience',story:'Maya uses one external identity to operate two approved locations and delegate a manager without reaching another franchise.',why:'Separate authentication from current business authorization and prove both an allowed and denied location request.',account:'Prepared Maya External ID test account',domain:'External tenant · verify the administrator profile',cases:[],highlights:['Show the associated user flow','Verify franchise and location context','Prove allowed and denied API outcomes'],admin:[step('Open the external tenant and inspect the franchise application, redirect URI and associated user flow.','The experience must use the intended External ID configuration.','Verify the tenant, application ID, user-flow association, identity providers and collected attributes.'),step('Inspect the trusted source or approval that maps Maya to Northstar Foods, the owner role and two locations.','Self-asserted profile data must not become business authorization.','Show a stable subject identifier, effective dates and the system of record for each assignment.'),step('Correlate sign-in and application events for one allowed and one denied location request.','Authentication success alone does not prove location authorization.','Match subject, application, timestamp, requested location and API decision.')],user:[step('Open the verified franchise application in Maya’s separate browser profile.','Keep the owner experience separate from the administrator session.','Use privately held credentials and the configured authentication method.'),step('Open Downtown or Airport, then attempt Riverside.','The audience should see the business boundary in action.','Show the real API allow and deny results; a hidden interface card is not proof.'),step('Open a prepared sensitive change or delegation task.','High-impact actions may need stronger assurance and narrower authorization.','Show the configured step-up or approval only if it is implemented and rehearsed.')],userTitle:'Experience Maya’s franchise command center',evidence:'Correlate External ID sign-in, business verification, token or session context and application authorization records.',caution:'The public portal is a labeled guided preview until a real franchise application and API are connected.',question:'Where does the application learn that this person represents this franchise, for these locations, right now?'};}
